        },
        {
            "label": "Future",
            "url": "/theory/verb-to-be/verb-to-be-future",
            "current": false
        },
        {
            "label": "There Is / There Are",
            "url": "/theory/verb-to-be/there-is-there-are",
            "current": false
        }
    ]
}

{
    "level": "A1",
    "intro": "Щоб зробити заперечення з <strong>to be</strong>, постав <strong>not</strong> після форми <strong>am / is / are</strong>.",
    "rules": [
        {
            "label": "am not",
            "color": "emerald",
            "text": "З <strong>I</strong> вживай <strong>am not</strong>.",
            "example": "I am not tired."
        },
        {
            "label": "is not / isn't",
            "color": "blue",
            "text": "З <strong>he / she / it</strong> вживай <strong>is not</strong> або <strong>isn't</strong>.",
            "example": "She isn't busy."
        },
        {
            "label": "are not / aren't",
            "color": "amber",
            "text": "З <strong>you / we / they</strong> вживай <strong>are not</strong> або <strong>aren't</strong>.",
            "example": "They aren't at home."
        }
    ]
}

{
    "title": "1. Форми заперечення",
    "intro": "Повна форма корисна для чіткого наголосу, коротка — для звичайного мовлення.",
    "items": [
        {
            "label": "I",
            "title": "am not",
            "subtitle": "I am not late."
        },
        {
            "label": "He / She / It",
            "title": "is not / isn't",
            "subtitle": "He is not hungry. / He isn't hungry."
        },
        {
            "label": "You / We / They",
            "title": "are not / aren't",
            "subtitle": "We are not ready. / We aren't ready."
        },
        {
            "label": "Pattern",
            "title": "Subject + be + not",
            "subtitle": "She is not here. / They are not students."
        }
    ]
}

{
    "title": "2. Як це працює",
    "sections": [
        {
            "label": "Повна форма",
            "color": "emerald",
            "description": "Повну форму часто використовують, коли хочуть звучати чіткіше або трохи сильніше підкреслити заперечення.",
            "examples": [
                {
                    "en": "She is not at school.",
                    "ua": "Вона не в школі."
                },
                {
                    "en": "We are not tired.",
                    "ua": "Ми не втомлені."
                }
            ]
        },
        {
            "label": "Коротка форма",
            "color": "blue",
            "description": "У звичайній розмові частіше вживають <strong>isn't</strong> і <strong>aren't</strong>.",
            "examples": [
                {
                    "en": "He isn't busy.",
                    "ua": "Він не зайнятий."
                },
                {
                    "en": "They aren't my friends.",
                    "ua": "Вони не мої друзі."
                }
            ]
        },
        {
            "label": "Контраст зі ствердженням",
            "color": "amber",
            "description": "Порівнюй ствердження і заперечення, щоб швидко бачити місце <strong>not</strong>.",
            "examples": [
                {
                    "en": "She is ready. → She isn't ready.",
                    "ua": "not стоїть після is."
                },
                {
                    "en": "They are at home. → They aren't at home.",
                    "ua": "not стоїть після are."
                }
            ]
        }
    ]
}

{
    "title": "3. Ствердження vs заперечення",
    "intro": "Форма to be не зникає: ми лише додаємо <strong>not</strong>.",
    "rows": [
        {
            "en": "I am at home.",
            "ua": "I am not at home.",
            "note": "am + not"
        },
        {
            "en": "She is happy.",
            "ua": "She isn't happy.",
            "note": "isn't = is not"
        },
        {
            "en": "They are students.",
            "ua": "They aren't students.",
            "note": "aren't = are not"
        }
    ],
    "warning": "📌 Не додавай <strong>do / does</strong> до заперечень з <strong>to be</strong>."
}

{
    "title": "4. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Ставити not перед формою to be.",
            "wrong": "❌ She not is tired.",
            "right": "✅ <span class=\"font-mono\">She is not tired.</span>"
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Додавати do до to be.",
            "wrong": "❌ They don't are ready.",
            "right": "✅ <span class=\"font-mono\">They aren't ready.</span>"
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Змішувати am not з isn't / aren't.",
            "wrong": "❌ I isn't late.",
            "right": "✅ <span class=\"font-mono\">I am not late.</span>"
        }
    ]
}

{
    "title": "5. Короткий підсумок",
    "items": [
        "Заперечення з <strong>to be</strong> = <strong>am / is / are + not</strong>.",
        "З <strong>I</strong> вживай <strong>am not</strong>.",
        "З <strong>he / she / it</strong> вживай <strong>is not</strong> або <strong>isn't</strong>.",
        "З <strong>you / we / they</strong> вживай <strong>are not</strong> або <strong>aren't</strong>.",
        "У запереченні з <strong>to be</strong> не потрібні <strong>do / does</strong>."
    ]
}

{
    "title": "Уроки Verb to Be",
    "items": [
        {
            "label": "Present Forms",
            "url": "/theory/verb-to-be/verb-to-be-present",
            "current": false
        },
        {
            "label": "Negatives",
            "url": "/theory/verb-to-be/verb-to-be-negatives",
            "current": true
        },
        {
            "label": "Questions and Short Answers",
            "url": "/theory/verb-to-be/verb-to-be-questions",
            "current": false
        },
        {
            "label": "Past Forms",
            "url": "/theory/verb-to-be/verb-to-be-past",
            "current": false
        },
        {
            "label": "Future",
            "url": "/theory/verb-to-be/verb-to-be-future",
            "current": false
        },
        {
            "label": "There Is / There Are",
            "url": "/theory/verb-to-be/there-is-there-are",
            "current": false
        }
    ]
}

{
    "level": "A1",
    "intro": "У питаннях з <strong>to be</strong> форма <strong>am / is / are</strong> стає <strong>перед підметом</strong>.",
    "rules": [
        {
            "label": "Am I...?",
            "color": "emerald",
            "text": "Починай питання з <strong>am</strong>, коли підмет <strong>I</strong>.",
            "example": "Am I late?"
        },
        {
            "label": "Is he / she / it...?",
            "color": "blue",
            "text": "З <strong>he / she / it</strong> став <strong>is</strong> перед підметом.",
            "example": "Is she at home?"
        },
        {
            "label": "Are you / we / they...?",
            "color": "amber",
            "text": "З <strong>you / we / they</strong> став <strong>are</strong> перед підметом.",
            "example": "Are they ready?"
        }
    ]
}

{
    "title": "1. Базові моделі питання",
    "intro": "Питання з to be будуються без do / does.",
    "items": [
        {
            "label": "I",
            "title": "Am I ...?",
            "subtitle": "Am I early?"
        },
        {
            "label": "He / She / It",
            "title": "Is he / she / it ...?",
            "subtitle": "Is he busy? / Is it cold?"
        },
        {
            "label": "You / We / They",
            "title": "Are you / we / they ...?",
            "subtitle": "Are we late? / Are they at school?"
        },
        {
            "label": "Short Answers",
            "title": "Yes, ... am / is / are.",
            "subtitle": "Yes, I am. / No, he isn't. / Yes, they are."
        }
    ]
}

{
    "title": "2. Як відповідати коротко",
    "sections": [
        {
            "label": "Yes",
            "color": "emerald",
            "description": "У короткій стверджувальній відповіді повтори форму <strong>am / is / are</strong>.",
            "examples": [
                {
                    "en": "Are you tired? — Yes, I am.",
                    "ua": "Так, я втомлений."
                },
                {
                    "en": "Is she here? — Yes, she is.",
                    "ua": "Так, вона тут."
                }
            ]
        },
        {
            "label": "No",
            "color": "blue",
            "description": "У короткій заперечній відповіді часто вживають скорочення <strong>isn't / aren't</strong>.",
            "examples": [
                {
                    "en": "Is he busy? — No, he isn't.",
                    "ua": "Ні, він не зайнятий."
                },
                {
                    "en": "Are they at home? — No, they aren't.",
                    "ua": "Ні, вони не вдома."
                }
            ]
        },
        {
            "label": "Порядок слів",
            "color": "amber",
            "description": "Порівняй ствердження і питання: форма <strong>to be</strong> переходить перед підметом.",
            "examples": [
                {
                    "en": "She is ready. → Is she ready?",
                    "ua": "Інверсія з to be."
                },
                {
                    "en": "They are at school. → Are they at school?",
                    "ua": "Без do / does."
                }
            ]
        }
    ]
}

{
    "title": "3. Питання і коротка відповідь",
    "intro": "У відповіді не повторюй усе речення: достатньо короткої форми.",
    "rows": [
        {
            "en": "Am I late?",
            "ua": "Yes, you are. / No, you aren't.",
            "note": "У відповіді на Am I...? часто кажуть you are / you aren't."
        },
        {
            "en": "Is she your teacher?",
            "ua": "Yes, she is. / No, she isn't.",
            "note": "is → she is / she isn't"
        },
        {
            "en": "Are they ready?",
            "ua": "Yes, they are. / No, they aren't.",
            "note": "are → they are / they aren't"
        }
    ],
    "warning": "📌 Не кажи <strong>Do they are...?</strong> або <strong>Yes, they do.</strong>"
}

{
    "title": "4. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Залишати порядок слів як у ствердженні.",
            "wrong": "❌ She is ready?",
            "right": "✅ <span class=\"font-mono\">Is she ready?</span>"
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Додавати do / does до to be.",
            "wrong": "❌ Do they are at home?",
            "right": "✅ <span class=\"font-mono\">Are they at home?</span>"
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Давати коротку відповідь з do.",
            "wrong": "❌ Yes, she does.",
            "right": "✅ <span class=\"font-mono\">Yes, she is.</span>"
        }
    ]
}

{
    "title": "5. Короткий підсумок",
    "items": [
        "Питання з <strong>to be</strong> = <strong>am / is / are + subject</strong>.",
        "З <strong>I</strong> починай з <strong>Am I...?</strong>",
        "З <strong>he / she / it</strong> починай з <strong>Is...?</strong>",
        "З <strong>you / we / they</strong> починай з <strong>Are...?</strong>",
        "У коротких відповідях повторюй форму <strong>to be</strong>: <strong>Yes, I am. / No, he isn't.</strong>"
    ]
}

